import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { format } from 'date-fns';

const Footer = () => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [location, setLocation] = useState({ city: 'Loading...', country: '' });

  useEffect(() => {
    // Update time every second
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);

    // Get user location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          try {
            const response = await fetch(
              `https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=${position.coords.latitude}&longitude=${position.coords.longitude}&localityLanguage=en`
            );
            const data = await response.json();
            setLocation({
              city: data.city || data.locality || 'Unknown',
              country: data.countryName || '',
            });
          } catch (error) {
            setLocation({ city: 'Unknown', country: '' });
          }
        },
        () => {
          setLocation({ city: 'Location unavailable', country: '' });
        }
      );
    }

    return () => clearInterval(timer);
  }, []);

  const quickLinks = [
    { path: '/', label: 'Home' },
    { path: '/monuments', label: 'Monuments' },
    { path: '/gallery', label: 'Gallery' },
    { path: '/contact', label: 'Contact' },
  ];

  return (
    <footer className="bg-gray-900 text-gray-300">
      {/* Scrolling Ticker */}
      <div className="bg-primary-700 text-white py-2 overflow-hidden">
        <div className="animate-scroll whitespace-nowrap">
          <span className="inline-block px-8">
            {format(currentTime, 'EEEE, MMMM dd, yyyy')}
          </span>
          <span className="inline-block px-8">
            {format(currentTime, 'HH:mm:ss')}
          </span>
          <span className="inline-block px-8">
            Location: {location.city}{location.country && `, ${location.country}`}
          </span>
          <span className="inline-block px-8">
            {format(currentTime, 'EEEE, MMMM dd, yyyy')}
          </span>
          <span className="inline-block px-8">
            {format(currentTime, 'HH:mm:ss')}
          </span>
          <span className="inline-block px-8">
            Location: {location.city}{location.country && `, ${location.country}`}
          </span>
        </div>
      </div>

      {/* Main Footer */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
          {/* About */}
          <div className="col-span-1 md:col-span-2">
            <div className="flex items-center space-x-3 mb-4">
              <div className="w-10 h-10 bg-gradient-to-br from-primary-600 to-primary-800 rounded-lg flex items-center justify-center">
                <span className="text-white text-xl font-bold">GH</span>
              </div>
              <h3 className="text-xl font-bold text-white">Global Heritage</h3>
            </div>
            <p className="text-gray-400 mb-4 leading-relaxed">
              Preserving and showcasing the world's most magnificent historical monuments and cultural heritage sites for future generations.
            </p>
            <div className="flex space-x-4">
              <a href="#" className="text-gray-400 hover:text-primary-400 transition-colors">
                <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z"/>
                </svg>
              </a>
